fun dazzColorScheme(
    family: DazzThemeFamily = DazzThemeFamily.Studio,
    darkTheme: Boolean = false,
): ColorScheme = when (family) {
    DazzThemeFamily.Studio -> if (darkTheme) DazzColorSchemes.StudioDark else DazzColorSchemes.StudioLight
    DazzThemeFamily.Bright -> if (darkTheme) DazzColorSchemes.BrightDark else DazzColorSchemes.BrightLight
    DazzThemeFamily.Frost -> if (darkTheme) DazzColorSchemes.FrostDark else DazzColorSchemes.FrostLight
    DazzThemeFamily.Graphite -> if (darkTheme) DazzColorSchemes.GraphiteDark else DazzColorSchemes.GraphiteLight
    DazzThemeFamily.Ember -> if (darkTheme) DazzColorSchemes.EmberDark else DazzColorSchemes.EmberLight
    DazzThemeFamily.Nocturne -> if (darkTheme) DazzColorSchemes.NocturneDark else DazzColorSchemes.NocturneLight
    DazzThemeFamily.OmarchyTokyoNight -> if (darkTheme) DazzColorSchemes.OmarchyTokyoNightDark else DazzColorSchemes.OmarchyTokyoNightLight
    DazzThemeFamily.OmarchyCatppuccin -> if (darkTheme) DazzColorSchemes.OmarchyCatppuccinDark else DazzColorSchemes.OmarchyCatppuccinLight
    DazzThemeFamily.OmarchyCatppuccinLatte -> if (darkTheme) DazzColorSchemes.OmarchyCatppuccinLatteDark else DazzColorSchemes.OmarchyCatppuccinLatteLight
    DazzThemeFamily.OmarchyEthereal -> if (darkTheme) DazzColorSchemes.OmarchyEtherealDark else DazzColorSchemes.OmarchyEtherealLight
    DazzThemeFamily.OmarchyEverforest -> if (darkTheme) DazzColorSchemes.OmarchyEverforestDark else DazzColorSchemes.OmarchyEverforestLight
    DazzThemeFamily.OmarchyFlexokiLight -> if (darkTheme) DazzColorSchemes.OmarchyFlexokiLightDark else DazzColorSchemes.OmarchyFlexokiLightLight
    DazzThemeFamily.OmarchyGruvbox -> if (darkTheme) DazzColorSchemes.OmarchyGruvboxDark else DazzColorSchemes.OmarchyGruvboxLight
    DazzThemeFamily.OmarchyHackerman -> if (darkTheme) DazzColorSchemes.OmarchyHackermanDark else DazzColorSchemes.OmarchyHackermanLight
    DazzThemeFamily.OmarchyKanagawa -> if (darkTheme) DazzColorSchemes.OmarchyKanagawaDark else DazzColorSchemes.OmarchyKanagawaLight
    DazzThemeFamily.OmarchyLastHorizon -> if (darkTheme) DazzColorSchemes.OmarchyLastHorizonDark else DazzColorSchemes.OmarchyLastHorizonLight
    DazzThemeFamily.OmarchyLumon -> if (darkTheme) DazzColorSchemes.OmarchyLumonDark else DazzColorSchemes.OmarchyLumonLight
    DazzThemeFamily.OmarchyLupine -> if (darkTheme) DazzColorSchemes.OmarchyLupineDark else DazzColorSchemes.OmarchyLupineLight
    DazzThemeFamily.OmarchyMatteBlack -> if (darkTheme) DazzColorSchemes.OmarchyMatteBlackDark else DazzColorSchemes.OmarchyMatteBlackLight
